   string config=Path.Combine(game,"ProjectZomboid64.json"),mods=Path.Combine(user,"mods","default.txt"),props=Path.Combine(user,"viewpoint-live.properties");
   File.WriteAllText(config,"{\"vmArgs\":[\"-Xmx6g\",\"-agentlib:zbNative\"],\"windows\":{\"10\":{\"vmArgs\":[\"-Xmx5g\"]}}}");File.WriteAllText(Path.Combine(game,"ProjectZomboid64.exe"),"fixture");File.WriteAllText(mods,"VERSION = 1,\nmods\n{\n mod = OtherMod,\n mod = ZombieBuddy,\n mod = Viewpoint,\n mod = PZVoxelStudioViewpoint,\n mod = ShootToThrillMultiplayer,\n mod = LaoYuTranslationJava,\n}\nmaps\n{\n}\n");File.WriteAllText(props,"# preserved\r\nmouse.invertY=false\r\nunknown.foo=unchanged\r\ngraphics.mode=Modern\r\ngraphics.pack=normal\r\n");
   object c=Activator.CreateInstance(type,new object[]{game,user,data,true});
   byte[] before=File.ReadAllBytes(config);var status=D(Call(c,"status"));Assert(!Convert.ToBoolean(((Dictionary<string,object>)status["task"])["active"]),"status read does not advertise a running task");D(Call(c,"memoryGet"));D(Call(c,"settingsGet"));D(Call(c,"shadersGet"));Assert(before.SequenceEqual(File.ReadAllBytes(config))&&!Directory.Exists(data),"reads never write configuration or preferences");
   Reject(()=>Call(c,"arbitraryExec"),"unknown action rejected");Reject(()=>Call(c,"componentsAction",new Dictionary<string,object>{{"component","chinese"},{"operation","erase"}}),"unknown operation rejected");
   Call(c,"componentsAction",new Dictionary<string,object>{{"component","chinese"},{"operation","uninstall"}});string after=File.ReadAllText(mods);Assert(!after.Contains("LaoYuTranslationJava")&&after.Contains("OtherMod")&&after.Contains("ShootToThrillMultiplayer")&&after.Contains("PZVoxelStudioViewpoint"),"Chinese card uninstall preserves unrelated components");
