   int downloads=0;using(var batch=new ModernController(game,user,data,true,(e,ids,progress,token,update)=>{downloads++;throw new Exception("fixture download unavailable");})){var result=D(batch.Execute("componentsAction",new Dictionary<string,object>{{"component","all"},{"operation","install"}}));string modFile=File.ReadAllText(sourceEngine.Mods);Assert(modFile.Contains("LaoYuTranslationJava")&&modFile.Contains("PZVoxelStudioViewpoint")&&modFile.Contains("OtherMod")&&Convert.ToString(result["message"]).Contains("[失败] shoot"),"all install continues Chinese after guns failure");Assert(downloads==1,"only missing shoot invokes external download boundary");byte[] cfg=File.ReadAllBytes(sourceEngine.Config);batch.Execute("componentsAction",new Dictionary<string,object>{{"component","models"},{"operation","uninstall"}});Assert(!File.ReadAllText(sourceEngine.Mods).Contains("PZVoxelStudioViewpoint")&&File.ReadAllText(sourceEngine.Mods).Contains("LaoYuTranslationJava")&&cfg.SequenceEqual(File.ReadAllBytes(sourceEngine.Config)),"models uninstall edits only scoped mod entry");}
   using(var partial=new ModernController(game,user,data,true,(e,ids,progress,token,update)=>{throw new Exception("fixture download unavailable");})){string lastProgress="";partial.Progress=(v,t)=>lastProgress=t;partial.Execute("componentsAction",new Dictionary<string,object>{{"component","all"},{"operation","install"}});Assert(lastProgress.Contains("部分"),"partial batch does not advertise complete success");}
   var entered=new ManualResetEvent(false);var release=new ManualResetEvent(false);Exception failure=null;CancellationToken localToken=default(CancellationToken);using(var active=new ModernController(game,user,data,true,(e,ids,progress,token,update)=>{localToken=token;entered.Set();WaitHandle.WaitAny(new[]{release,token.WaitHandle});token.ThrowIfCancellationRequested();return new Dictionary<ulong,string>();})){var worker=new Thread(()=>{try{active.Execute("componentsAction",new Dictionary<string,object>{{"component","shoot"},{"operation","install"}});}catch(Exception ex){failure=ex;}});worker.Start();Assert(entered.WaitOne(5000),"download boundary entered");Assert(active.Busy,"active operation exposes busy");Reject(()=>active.Execute("status",null),"reads cannot race active writes");Call(active,"cancel",new Dictionary<string,object>{{"scope","hall"},{"requestId","absent"}});Assert(!localToken.IsCancellationRequested&&active.Busy,"hall-only cancel never cancels a local mutation");active.Cancel();Assert(worker.Join(5000)&&failure is OperationCanceledException&&!active.Busy,"cancel stops download and releases busy");Assert(D(active.Execute("status",null)).ContainsKey("gamePath"),"fresh action resets cancellation token");}entered.Dispose();release.Dispose();
   using(var shader=new ModernController(game,user,data,true)){string dir=Path.Combine(user,"viewpoint-shaderpacks");Directory.CreateDirectory(dir);string zip=Path.Combine(dir,"fixture.zip");using(var archive=System.IO.Compression.ZipFile.Open(zip,System.IO.Compression.ZipArchiveMode.Create)){using(var writer=new StreamWriter(archive.CreateEntry("shaders/a.fsh").Open()))writer.Write("fixture");}var first=D(shader.Execute("shadersGet",null));File.Delete(zip);using(var archive=System.IO.Compression.ZipFile.Open(zip,System.IO.Compression.ZipArchiveMode.Create)){using(var writer=new StreamWriter(archive.CreateEntry("shaders/a.fsh").Open()))writer.Write("different bytes");}Reject(()=>shader.Execute("shaderSelect",new Dictionary<string,object>{{"id","minecraft-fixture"},{"stamp",first["stamp"]}}),"shader snapshot detects changed valid ZIP bytes");}
  }
